/**
 * n8n Code node
 * Mode: Run Once for All Items
 *
 * Handles:
 * - AI output as a JSON string or object
 * - Escaped newlines and Markdown code fences
 * - 50 separate input items or an array of 50 students
 * - Basic validation and data normalization
 */

const items = $input.all();

function parseAIOutput(value) {
  // Already a parsed object or array
  if (value && typeof value === "object") {
    return value;
  }

  if (typeof value !== "string") {
    throw new Error("AI output is not a JSON string or object");
  }

  let text = value.trim();

  // Remove Markdown code fences
  text = text
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  // Handle literal escaped newlines from AI output
  if (text.startsWith("{\\n") || text.startsWith("[\\n")) {
    text = text.replace(/\\r\\n/g, "\n").replace(/\\n/g, "\n");
  }

  // Parse JSON directly first
  try {
    return JSON.parse(text);
  } catch (error) {
    // If additional text surrounds the JSON, extract the JSON block
    const firstObject = text.indexOf("{");
    const firstArray = text.indexOf("[");
    const starts = [firstObject, firstArray].filter(
      index => index !== -1
    );

    if (starts.length === 0) {
      throw new Error("No JSON object or array found in AI output");
    }

    const start = Math.min(...starts);
    const opening = text[start];
    const closing = opening === "{" ? "}" : "]";
    const end = text.lastIndexOf(closing);

    if (end < start) {
      throw new Error("Incomplete JSON returned by AI");
    }

    return JSON.parse(text.slice(start, end + 1));
  }
}

function cleanStudent(student) {
  if (!student || typeof student !== "object" || Array.isArray(student)) {
    throw new Error("Student record must be a JSON object");
  }

  const result = { ...student };

  // Normalize text
  for (const key of [
    "student_id",
    "student_name",
    "class",
    "section",
    "gender",
    "parent_guardian_name",
    "parent_email",
    "parent_phone",
    "admission_date",
    "student_status"
  ]) {
    if (result[key] != null) {
      result[key] = String(result[key]).trim();
    }
  }

  // Student name: Title Case
  if (result.student_name) {
    result.student_name = result.student_name
      .toLowerCase()
      .replace(/\b([a-z])/g, letter => letter.toUpperCase());
  }

  // Parent/guardian name: Title Case
  if (result.parent_guardian_name) {
    result.parent_guardian_name = result.parent_guardian_name
      .toLowerCase()
      .replace(/\b([a-z])/g, letter => letter.toUpperCase());
  }

  // Email validation
  if (result.parent_email) {
    result.parent_email = result.parent_email.toLowerCase();

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailPattern.test(result.parent_email)) {
      result.parent_email = "INVALID_EMAIL";
    }
  } else {
    result.parent_email = "INVALID_EMAIL";
  }

  // Phone: keep digits only; require at least 10 digits
  const phone = String(result.parent_phone ?? "").replace(/\D/g, "");

  result.parent_phone = phone.length < 10 ? "MISSING" : phone;

  // Normalize numeric fee fields
  for (const key of [
    "annual_fee_inr",
    "fees_paid_inr",
    "fees_due_inr"
  ]) {
    if (result[key] !== "" && result[key] != null) {
      const number = Number(result[key]);

      if (Number.isFinite(number)) {
        result[key] = number;
      }
    }
  }

  // Fee status:
  // Preserve meaningful existing statuses.
  // If supplied as a boolean, keep it boolean.
  if (typeof result.fee_status === "string") {
    const status = result.fee_status.trim().toLowerCase();

    if (["paid", "partial", "unpaid"].includes(status)) {
      result.fee_status =
        status.charAt(0).toUpperCase() + status.slice(1);
    } else if (["yes", "true"].includes(status)) {
      result.fee_status = true;
    } else if (["no", "false"].includes(status)) {
      result.fee_status = false;
    }
  }

  // If fee status is boolean, derive it from outstanding fees
  // when a due amount is available.
  if (
    typeof result.fee_status === "boolean" &&
    Number.isFinite(result.fees_due_inr)
  ) {
    result.fee_status = result.fees_due_inr === 0;
  }

  // Normalize dates to YYYY-MM-DD
  for (const key of ["date_of_birth", "admission_date"]) {
    if (result[key]) {
      const value = String(result[key]).trim();
      const match = value.match(
        /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/
      );

      if (match) {
        const [, year, month, day] = match;
        result[key] =
          `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
      }
    }
  }

  // Keep student status consistently formatted
  if (result.student_status) {
    result.student_status =
      result.student_status.charAt(0).toUpperCase() +
      result.student_status.slice(1).toLowerCase();
  }

  return result;
}

const output = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json;

  // Common AI node output fields; adjust if yours differs.
  const raw =
    input.output ??
    input.text ??
    input.response ??
    input.content ??
    input.message ??
    input;

  try {
    const parsed = parseAIOutput(raw);

    // Support one student object or an array of students.
    const students = Array.isArray(parsed) ? parsed : [parsed];

    for (const student of students) {
      output.push({
        json: cleanStudent(student)
      });
    }
  } catch (error) {
    // Include the original item index to help troubleshoot failures.
    throw new Error(
      `Failed to parse input item ${i + 1}: ${error.message}`
    );
  }
}

return output;
